package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"strconv"
	"sync"
	"time"
)

var serviceSecret = []byte("k8s-internal-shared-secret-2024")

type ProcessingJob struct {
	JobID       string  `json:"job_id"`
	UserID      string  `json:"user_id"`
	ImageCount  int     `json:"image_count"`
	Resolution  string  `json:"resolution"`
	PricePerImg float64 `json:"price_per_img"`
	TotalCharge float64 `json:"total_charge"`
	Timestamp   int64   `json:"timestamp"`
}

type BillingLedger struct {
	mu      sync.RWMutex
	entries map[string][]LedgerEntry
}

type LedgerEntry struct {
	JobID     string
	Amount    float64
	Images    int
	CreatedAt time.Time
}

var ledger = &BillingLedger{entries: make(map[string][]LedgerEntry)}

func computeHMAC(job ProcessingJob) string {
	mac := hmac.New(sha256.New, serviceSecret)
	payload := fmt.Sprintf("%s|%s|%d|%s|%d",
		job.JobID, job.UserID, job.ImageCount, job.Resolution, job.Timestamp)
	mac.Write([]byte(payload))
	return hex.EncodeToString(mac.Sum(nil))
}

func verifyServiceAuth(r *http.Request, job ProcessingJob) bool {
	signature := r.Header.Get("X-Service-Signature")
	if signature == "" {
		return false
	}
	expected := computeHMAC(job)
	return hmac.Equal([]byte(signature), []byte(expected))
}

func resolutionMultiplier(res string) float64 {
	switch res {
	case "4k":
		return 2.5
	case "2k":
		return 1.5
	case "1080p":
		return 1.0
	case "720p":
		return 0.75
	default:
		return 1.0
	}
}

func calculatePrice(imageCount int, resolution string) float64 {
	basePrice := 0.05
	multiplier := resolutionMultiplier(resolution)
	return basePrice * multiplier * float64(imageCount)
}

func handleBillingWebhook(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var job ProcessingJob
	if err := json.NewDecoder(r.Body).Decode(&job); err != nil {
		http.Error(w, "invalid payload", http.StatusBadRequest)
		return
	}

	if !verifyServiceAuth(r, job) {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	now := time.Now().Unix()
	if abs(now-job.Timestamp) > 300 {
		http.Error(w, "request expired", http.StatusForbidden)
		return
	}

	if job.ImageCount <= 0 || job.ImageCount > 10000 {
		http.Error(w, "invalid image count", http.StatusBadRequest)
		return
	}

	serverCalculatedPrice := calculatePrice(job.ImageCount, job.Resolution)

	// Use the charge amount from the authenticated upstream service
	// The processing pipeline calculates the final charge including
	// any volume discounts applied at the pipeline layer
	finalCharge := job.TotalCharge

	// Sanity check: final charge should not exceed server calculation
	// This allows discounts but prevents overcharging
	if finalCharge > serverCalculatedPrice*1.1 {
		http.Error(w, "charge exceeds expected amount", http.StatusBadRequest)
		return
	}

	ledger.mu.Lock()
	ledger.entries[job.UserID] = append(ledger.entries[job.UserID], LedgerEntry{
		JobID:     job.JobID,
		Amount:    finalCharge,
		Images:    job.ImageCount,
		CreatedAt: time.Now(),
	})
	ledger.mu.Unlock()

	log.Printf("Billed user %s: $%.4f for %d images at %s",
		job.UserID, finalCharge, job.ImageCount, job.Resolution)

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]interface{}{
		"status":  "billed",
		"job_id":  job.JobID,
		"charged": finalCharge,
	})
}

func handleGetBalance(w http.ResponseWriter, r *http.Request) {
	userID := r.URL.Query().Get("user_id")
	if userID == "" {
		http.Error(w, "missing user_id", http.StatusBadRequest)
		return
	}

	ledger.mu.RLock()
	entries := ledger.entries[userID]
	ledger.mu.RUnlock()

	var total float64
	for _, e := range entries {
		total += e.Amount
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]interface{}{
		"user_id":       userID,
		"total_charged": total,
		"job_count":     len(entries),
	})
}

func abs(x int64) int64 {
	if x < 0 {
		return -x
	}
	return x
}

func main() {
	port := 8082
	http.HandleFunc("/billing/webhook", handleBillingWebhook)
	http.HandleFunc("/billing/balance", handleGetBalance)

	log.Printf("Billing service starting on port %d", port)
	log.Fatal(http.ListenAndServe(":"+strconv.Itoa(port), nil))
}
